@push('scripts')<script>
function filterStock() { const search = document.getElementById('stockSearch').value.toLowerCase(); const category = document.getElementById('stockCategory').value; const ruptures = document.getElementById('stockRuptures').checked; document.querySelectorAll('#stockStatusTable tbody tr').forEach(row => { const text = row.textContent.toLowerCase(); const matchSearch = text.includes(search); const matchCategory = !category || text.includes(category); const isRupture = row.classList.contains('table-danger'); row.style.display = matchSearch && matchCategory && (!ruptures || isRupture) ? '' : 'none'; }); } document.getElementById('stockSearch').addEventListener('input', filterStock); document.getElementById('stockCategory').addEventListener('change', filterStock); document.getElementById('stockRuptures').addEventListener('change', filterStock);
</script>@endpush
